require_once __DIR__.'/../includes/bootstrap.php';$admin=require_admin();$db=$GLOBALS['pdo'];$counts=[];$queries=['users'=>'SELECT COUNT(*) FROM users','active_users'=>'SELECT COUNT(*) FROM users WHERE is_active=1','workspaces'=>'SELECT COUNT(*) FROM workspaces','datasets'=>'SELECT COUNT(*) FROM datasets','ai_queries'=>'SELECT COUNT(*) FROM ai_queries','storage_bytes'=>'SELECT COALESCE(SUM(storage_bytes),0) FROM datasets','subscriptions'=>'SELECT COUNT(*) FROM subscriptions','confirmed_revenue'=>'SELECT COALESCE(SUM(amount_idr),0) FROM payments WHERE status="confirmed"'];foreach($queries as $key=>$sql)$counts[$key]=$db->query($sql)->fetchColumn();$months=[];for($i=5;$i>=0;$i--){$d=new DateTimeImmutable('first day of this month');$d=$d->modify('-'.$i.' months');$months[$d->format('Y-m')]=['label'=>$d->format('M y'),'users'=>0,'datasets'=>0,'queries'=>0,'revenue'=>0];}$fill=['users'=>['users','created_at'],'datasets'=>['datasets','created_at']];foreach($fill as $key=>[$table,$date]){$st=$db->query('SELECT DATE_FORMAT('.$date.',"%Y-%m") month_key,COUNT(*) total FROM '.$table.' WHERE '.$date.'>=DATE_SUB(CURDATE(),INTERVAL 6 MONTH) GROUP BY month_key');foreach($st->fetchAll() as $row)if(isset($months[$row['month_key']]))$months[$row['month_key']][$key]=(int)$row['total'];}$st=$db->query('SELECT month_key,SUM(units) total FROM usage_logs WHERE usage_type="ai_query" AND month_key>=DATE_FORMAT(DATE_SUB(CURDATE(),INTERVAL 5 MONTH),"%Y-%m") GROUP BY month_key');foreach($st->fetchAll() as $row)if(isset($months[$row['month_key']]))$months[$row['month_key']]['queries']=(int)$row['total'];$st=$db->query('SELECT DATE_FORMAT(confirmed_at,"%Y-%m") month_key,SUM(amount_idr) total FROM payments WHERE status="confirmed" AND confirmed_at>=DATE_SUB(CURDATE(),INTERVAL 6 MONTH) GROUP BY month_key');foreach($st->fetchAll() as $row)if(isset($months[$row['month_key']]))$months[$row['month_key']]['revenue']=(int)$row['total'];$series=array_values($months);$activity=['labels'=>array_column($series,'label'),'values'=>array_column($series,'queries'),'type'=>'line'];$st=$db->query('SELECT a.id,a.action,a.entity_type,a.created_at,u.name actor FROM audit_logs a LEFT JOIN users u ON u.id=a.actor_id ORDER BY a.created_at DESC LIMIT 8');$recent=$st->fetchAll();require_once __DIR__.'/../includes/header.php';$layout='admin';datanix_header('Admin overview','home',$layout);
?>
